function rosterSlot(club,k,li,ci){
 const real=li===0 ? (teams[ci][2][k] || null) : li===10 ? [englishPlayers[club][k],englishPositions[k],Math.min(91,Math.max(69,(englishOvr[club]||77)+(k%5)-2))] : (knownForeign[club]||[])[k];
 if(real) return {id:'s'+li+'_'+ci+'_'+k,name:real[0],pos:real[1],ovr:real[2],value:Math.max(1,Math.round((real[2]-65)*1.1*10)/10),verified:false};
 const ovr=Math.max(61,76-(ci%5)-(li>0?2:0)+(k%4));
 return {id:'s'+li+'_'+ci+'_'+k,name:'Atleta a confirmar '+(k+1),pos:positions18[k],ovr,value:Math.max(1,Math.round((ovr-65)*1.1*10)/10),placeholder:true};
}
function completeRoster(list,club,li,ci){
 const result=list.slice(0,18).map(x=>({...x}));
 for(let k=result.length;k<18;k++)result.push(rosterSlot(club,k,li,ci));
 return result;
}
const leaguePools=countryLeagues.map((league,li)=>league.clubs.map((name,i)=>({id:li+':'+i,name,country:li,ovr:li===0?Math.round(teams[i][2].reduce((s,p)=>s+p[2],0)/teams[i][2].length):Math.max(68,82-i%7+(li===1?2:0)),players:li===0?null:Array.from({length:18},(_,k)=>rosterSlot(name,k,li,i))})));
function countryOfTeam(id){return Math.floor(id/1000)}
function clubUid(li,i){return li*1000+i}
function getClubByUid(uid){return leaguePools[Math.floor(uid/1000)]?.[uid%1000]}
function makeLeagueTable(li){return leaguePools[li].map((t,i)=>({id:i,pts:0,p:0,w:0,d:0,l:0,gf:0,ga:0}))}
function circleSchedule(n){let arr=Array.from({length:n},(_,i)=>i);if(n%2){arr.push(-1);n++}const out=[];for(let r=0;r<n-1;r++){let matches=[];for(let j=0;j<n/2;j++){const a=arr[j],b=arr[n-1-j];if(a>=0&&b>=0)matches.push([a,b])}out.push(matches);arr=[arr[0],arr[n-1],...arr.slice(1,n-1)]}return out}
function ensureExpansion(){
 if(!state.country && state.country!==0)state.country=0;
 if(!state.countryTables)state.countryTables=countryLeagues.map((_,li)=>makeLeagueTable(li));
 while(state.countryTables.length<countryLeagues.length)state.countryTables.push(makeLeagueTable(state.countryTables.length));
 if(!state.countryRounds)state.countryRounds=countryLeagues.map(()=>0);
 while(state.countryRounds.length<countryLeagues.length)state.countryRounds.push(0);
 if(!state.foreignPlayers)state.foreignPlayers=leaguePools.map((league,li)=>li===0?null:league.map(t=>t.players.map(p=>({...p}))));
 state.players=state.players.map((arr,i)=>completeRoster(arr,teams[i][0],0,i));
 state.foreignPlayers=leaguePools.map((league,li)=>li===0?null:league.map((t,i)=>completeRoster((state.foreignPlayers[li]?.[i]||[]).map((p,k)=>p.name?.startsWith('Jogador ')?rosterSlot(t.name,k,li,i):p),t.name,li,i)));
 // Preencher vagas provisórias dos clubes argentinos com referências nomeadas, sem apagar transferências feitas.
 for(let ci=0;ci<countryLeagues[1].clubs.length;ci++){
  const club=countryLeagues[1].clubs[ci], refs=knownForeign[club]||[], roster=state.foreignPlayers[1][ci];
  const named=new Set(roster.filter(p=>!p.placeholder).map(p=>p.name));
  for(const ref of refs){if(named.has(ref[0]))continue;const slot=roster.findIndex(p=>p.placeholder);
   if(slot<0)break;roster[slot]={id:'ar'+ci+'_'+slot,name:ref[0],pos:ref[1],ovr:ref[2],value:Math.max(1,Math.round((ref[2]-65)*1.1*10)/10),verified:false};named.add(ref[0]);}
 }
 if(state.viewClub===undefined)state.viewClub=null;
 if(!state.continental)state.continental={year:state.year,round:0,fixtures:[],results:[],champion:null,qualified:false};
 if(!state.careerCountry && state.careerCountry!==0)state.careerCountry=0;
 if(!state.careerClub && state.careerClub!==0)state.careerClub=state.club;
 if(!state.continentalHistory)state.continentalHistory=[];
}

// Estatísticas fictícias geradas por partida; não representam dados oficiais.
function statsInit(){if(!state.scorers||state.scorers.year!==state.year)state.scorers={year:state.year,competitions:{}}}
function playerForEvent(uid){const li=Math.floor(uid/1000),ci=uid%1000;const roster=li===0?state.players[ci]:state.foreignPlayers[li]?.[ci];return (roster||[]).filter(p=>!p.placeholder&&p.name&&!p.name.startsWith('Atleta a confirmar'));}
function pickEventPlayer(uid,assist=false){const players=playerForEvent(uid);if(!players.length)return null;const weights=players.map(p=>{const pos=(p.pos||'').toUpperCase();let w=assist?(/MEI|MC|PD|PE|VOL|LD|LE/.test(pos)?4:1):(/ATA|PD|PE/.test(pos)?6:/MEI|MC/.test(pos)?3:1);return w*Math.max(.5,(p.ovr||70)/75)});let n=Math.random()*weights.reduce((a,b)=>a+b,0);for(let i=0;i<players.length;i++){n-=weights[i];if(n<=0)return players[i]}return players[players.length-1]}
function recordGoals(comp,a,b,x,y){statsInit();const stats=state.scorers.competitions[comp]||(state.scorers.competitions[comp]={});for(const [uid,goals] of [[a,x],[b,y]])for(let i=0;i<goals;i++){const scorer=pickEventPlayer(uid);if(!scorer)continue;const key=uid+'|'+String(scorer.id??scorer.name);const row=stats[key]||(stats[key]={name:scorer.name,uid,goals:0,assists:0});row.goals++;if(Math.random()<.73){const helpers=playerForEvent(uid).filter(p=>p!==scorer&&String(p.id??p.name)!==String(scorer.id??scorer.name));if(helpers.length){const helper=helpers[Math.floor(Math.random()*helpers.length)];const hk=uid+'|'+String(helper.id??helper.name);const hrow=stats[hk]||(stats[hk]={name:helper.name,uid,goals:0,assists:0});hrow.assists++}}}}
function statsCompetitionNames(){return [...countryLeagues.map((l,i)=>({key:'league-'+i,name:l.flag+' '+l.name})),{key:'libertadores',name:'🏆 Libertadores'},{key:'sudamericana',name:'🏆 Sul-Americana'},...countryLeagues.map((l,i)=>({key:'cup-'+i,name:'🏆 Copa Nacional — '+l.name})),{key:'world',name:'🌍 Super Mundial'}]}
function statsTable(comp,kind){statsInit();const arr=Object.values(state.scorers.competitions[comp]||{}).filter(x=>x[kind]>0).sort((a,b)=>b[kind]-a[kind]||(kind==='goals'?b.assists-a.assists:b.goals-a.goals)).slice(0,15);return `<div class="tablewrap"><table><thead><tr><th>#</th><th>JOGADOR</th><th>CLUBE</th><th>${kind==='goals'?'GOLS':'ASSIST.'}</th></tr></thead><tbody>${arr.map((x,i)=>`<tr><td>${i+1}</td><td>${x.name}</td><td>${getClubByUid(x.uid)?.name||'Clube'}</td><td><b>${x[kind]}</b></td></tr>`).join('')||'<tr><td colspan="4">Ainda não há estatísticas registradas nesta competição.</td></tr>'}</tbody></table></div>`}
function statsWidget(comp){return `<section class="panel"><h3>⚽ Artilharia</h3>${statsTable(comp,'goals')}</section><section class="panel"><h3>🎯 Líderes em assistências</h3>${statsTable(comp,'assists')}</section>`}
function renderStatistics(){const names=statsCompetitionNames();const selected=names.find(n=>n.key===state.statsComp)||names[0];return `<section class="panel"><h3>⚽ Artilharia e 🎯 assistências — ${state.year}</h3><p class="muted">Estatísticas fictícias das partidas simuladas nesta versão. Partidas de versões anteriores não possuem autores de gols registrados.</p><select id="statsSelect" style="width:100%;padding:12px;border-radius:8px;background:#17251b;color:white;border:1px solid #516453">${names.map(n=>`<option value="${n.key}" ${n.key===selected.key?'selected':''}>${n.name}</option>`).join('')}</select></section>${statsWidget(selected.key)}`}

function scorePower(ovrA,ovrB){return Math.max(0,Math.min(6,Math.round(1.3+(ovrA-ovrB)/13+(Math.random()-.5)*3.6)))}
function getPower(uid){let li=Math.floor(uid/1000),idx=uid%1000;if(li===0)return strength(idx);let p=state.foreignPlayers[li][idx];return p.reduce((s,x)=>s+x.ovr,0)/p.length}
function allClubNames(){return leaguePools.flat().map(t=>t.name)}
function simulateForeignRound(li){const rounds=circleSchedule(leaguePools[li].length),r=state.countryRounds[li];if(r>=rounds.length)return false;for(let [a,b] of rounds[r]){const x=scorePower(getPower(clubUid(li,a)),getPower(clubUid(li,b))),y=scorePower(getPower(clubUid(li,b)),getPower(clubUid(li,a)));updateLeagueTable(state.countryTables[li],a,b,x,y);recordGoals("league-"+li,clubUid(li,a),clubUid(li,b),x,y)}state.countryRounds[li]++;return true}
function updateLeagueTable(table,a,b,x,y){let A=table[a],B=table[b];A.p++;B.p++;A.gf+=x;A.ga+=y;B.gf+=y;B.ga+=x;if(x>y){A.w++;B.l++;A.pts+=3}else if(y>x){B.w++;A.l++;B.pts+=3}else{A.d++;B.d++;A.pts++;B.pts++}}
function leagueRank(table){return [...table].sort((a,b)=>b.pts-a.pts||((b.gf-b.ga)-(a.gf-a.ga))||b.gf-a.gf)}
function newLibertadores(){
 // 32 participantes de 10 países, incluindo 4 do Brasil e 4 da Argentina.
 const quota=[4,4,3,3,3,3,3,3,3,3];let entrants=[];
 for(let li=0;li<10;li++){const ranks=li===0?tableSorted():leagueRank(state.countryTables[li]);for(let t of ranks.slice(0,quota[li]))entrants.push(clubUid(li,t.id))}
 // Embaralhamento determinístico da ordem por país para distribuir grupos.
 entrants=entrants.sort((a,b)=>(a%1000)-(b%1000)||Math.floor(a/1000)-Math.floor(b/1000));
 const groups=Array.from({length:8},(_,i)=>entrants.slice(i*4,i*4+4));
 state.continental={year:state.year,round:0,groups,groupTables:groups.map(g=>g.map(uid=>({uid,pts:0,p:0,gf:0,ga:0}))),results:[],knockout:null,champion:null,qualified:groups.some(g=>g.includes(clubUid(state.careerCountry,state.careerClub)))};
}
function newSudamericana(){
 const quotas=[4,4,3,3,3,3,3,3,3,3];let entrants=[];
 for(let li=0;li<10;li++){
  const rank=li===0?tableSorted():leagueRank(state.countryTables[li]);
  const picked=rank.slice(quotas[li],quotas[li]*2);
  // Leagues with 10 teams have enough slots; Brazilian league has 20.
  for(const t of picked)entrants.push(clubUid(li,t.id));
 }
 // Ensure 32 unique entries if a league is small.
 const used=new Set(entrants);
 for(let li=0;li<countryLeagues.length&&entrants.length<32;li++)for(let ci=0;ci<countryLeagues[li].clubs.length&&entrants.length<32;ci++){
  const uid=clubUid(li,ci);if(!used.has(uid)){entrants.push(uid);used.add(uid)}
 }
 entrants=entrants.slice(0,32);
 const groups=Array.from({length:8},(_,i)=>entrants.slice(i*4,i*4+4));
 state.sudamericana={year:state.year,round:0,groups,groupTables:groups.map(g=>g.map(uid=>({uid,pts:0,p:0,gf:0,ga:0}))),results:[],knockout:null,champion:null,qualified:groups.some(g=>g.includes(clubUid(state.careerCountry,state.careerClub)))};
}
function simulateSudamericana(){
 const c=state.sudamericana;if(!c||c.champion!==null)return;
 if(c.round<6){let fixtures=[[0,1],[2,3]];
  if(c.round%3===1)fixtures=[[0,2],[1,3]];
  if(c.round%3===2)fixtures=[[0,3],[1,2]];
  if(c.round>=3)fixtures=fixtures.map(([a,b])=>[b,a]);
  for(let gi=0;gi<8;gi++)for(const [a,b] of fixtures){
   const u=c.groups[gi][a],v=c.groups[gi][b],x=scorePower(getPower(u),getPower(v)),y=scorePower(getPower(v),getPower(u));
   const A=c.groupTables[gi][a],B=c.groupTables[gi][b];
   A.p++;B.p++;A.gf+=x;A.ga+=y;B.gf+=y;B.ga+=x;
   if(x>y)A.pts+=3;else if(y>x)B.pts+=3;else{A.pts++;B.pts++}
   c.results.push({round:'Grupos '+(c.round+1),a:u,b:v,x,y});recordGoals('libertadores',u,v,x,y);recordGoals('sudamericana',u,v,x,y);
  }
  c.round++;
  if(c.round===6)c.knockout=c.groupTables.flatMap(t=>[...t].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)).slice(0,2).map(x=>x.uid));
 }else{
  const winners=[];for(let i=0;i<c.knockout.length;i+=2){const a=c.knockout[i],b=c.knockout[i+1];let x=scorePower(getPower(a),getPower(b)),y=scorePower(getPower(b),getPower(a));
   if(x===y){if(Math.random()<.5)x++;else y++}
   winners.push(x>y?a:b);c.results.push({round:['Oitavas','Quartas','Semifinal','Final'][c.round-6],a,b,x,y});recordGoals('libertadores',a,b,x,y);recordGoals('sudamericana',a,b,x,y);
  }
  c.knockout=winners;c.round++;
  if(winners.length===1){c.champion=winners[0];state.budget+=c.champion===clubUid(state.careerCountry,state.careerClub)?22:0;}
 }
 save();render();alertMsg(c.champion!==null?'🏆 Campeão da Sul-Americana: '+getClubByUid(c.champion).name:'Sul-Americana: etapa avançada!');
}
function cupsFinished(){return state.continental?.champion!==null && state.sudamericana?.champion!==null && extraCupsFinished()}
function simulateLibertadores(){const c=state.continental;if(c.champion!==null)return;
 if(c.round<6){let fixtures=[[0,1],[2,3]];if(c.round%3===1)fixtures=[[0,2],[1,3]];if(c.round%3===2)fixtures=[[0,3],[1,2]];if(c.round>=3)fixtures=fixtures.map(([a,b])=>[b,a]);
 for(let gi=0;gi<8;gi++){for(let [a,b] of fixtures){let u=c.groups[gi][a],v=c.groups[gi][b],x=scorePower(getPower(u),getPower(v)),y=scorePower(getPower(v),getPower(u));let A=c.groupTables[gi][a],B=c.groupTables[gi][b];A.p++;B.p++;A.gf+=x;A.ga+=y;B.gf+=y;B.ga+=x;if(x>y)A.pts+=3;else if(y>x)B.pts+=3;else{A.pts++;B.pts++}c.results.push({round:'Grupos '+(c.round+1),a:u,b:v,x,y})}}c.round++;
 if(c.round===6){const qualifiers=c.groupTables.flatMap(t=>[...t].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)).slice(0,2).map(x=>x.uid));c.knockout=qualifiers;}
 }else{
 let winners=[];for(let i=0;i<c.knockout.length;i+=2){const a=c.knockout[i],b=c.knockout[i+1];let x=scorePower(getPower(a),getPower(b)),y=scorePower(getPower(b),getPower(a));if(x===y){if(Math.random()<.5)x++;else y++}winners.push(x>y?a:b);c.results.push({round:['Oitavas','Quartas','Semifinal','Final'][c.round-6],a,b,x,y})}c.knockout=winners;c.round++;if(winners.length===1){c.champion=winners[0];state.continentalHistory.push({year:state.year,champion:c.champion});state.budget+=c.champion===clubUid(state.careerCountry,state.careerClub)?35:0;}}
 save();render();alertMsg(c.champion!==null?'🏆 Campeão: '+getClubByUid(c.champion).name:'Libertadores: etapa avançada!');
}
function renderSouth(){let li=state.country;let league=countryLeagues[li],rank=li===0?tableSorted():leagueRank(state.countryTables[li]);let max=circleSchedule(league.clubs.length).length;return `<section class="panel"><h3>🌍 Ligas nacionais</h3><p class="muted">Explore as 10 ligas sul-americanas e a liga inglesa. Clubes são representativos, e resultados são fictícios. Formatos simplificados.</p><div class="leaguechips">${countryLeagues.map((l,i)=>`<button class="chip ${i===li?'selected':''}" data-country="${i}">${l.flag} ${l.name}</button>`).join('')}</div><div class="row"><b>${league.flag} ${league.name}</b><span>Rodada ${li===0?state.round:state.countryRounds[li]}/${max}</span></div>${li!==0?`<button class="primary" id="simcountry" ${state.countryRounds[li]>=max||li===careerLeague()?'disabled':''}>▶ Simular rodada da liga</button>`:'<p class="muted">A Série A brasileira avança pela Central do Treinador.</p>'}<div class="tablewrap"><table><thead><tr><th>#</th><th>CLUBE</th><th>PTS</th><th>J</th><th>V</th><th>SG</th></tr></thead><tbody>${rank.map((t,i)=>`<tr><td>${i+1}</td><td><button class="club-link" data-viewclub="${li}:${t.id}">${league.clubs[t.id]}</button></td><td><b>${t.pts}</b></td><td>${t.p}</td><td>${t.w}</td><td>${t.gf-t.ga}</td></tr>`).join('')}</tbody></table></div></section>`}
function renderClubRoster(){const [li,ci]=(state.viewClub||'0:0').split(':').map(Number);const team=leaguePools[li][ci];const roster=li===0?state.players[ci]:state.foreignPlayers[li][ci];return `<section class="panel"><button class="secondary" id="backclubs">← Voltar às ligas</button><h3>${team.name} — ${countryLeagues[li].flag} ${countryLeagues[li].name}</h3><p class="muted">18 vagas por equipe. Nomes identificados são referências históricas/recentes, sem vínculo confirmado em novembro de 2026. “Atleta a confirmar” não representa jogador real cadastrado.</p><div class="tablewrap"><table><thead><tr><th>#</th><th>JOGADOR</th><th>POSIÇÃO</th><th>GER</th><th>VALOR</th></tr></thead><tbody>${roster.map((p,i)=>`<tr><td>${i+1}</td><td>${p.name}</td><td>${p.pos}</td><td class="rating">${p.ovr}</td><td>${fmt(p.value)}</td></tr>`).join('')}</tbody></table></div></section>`}
function renderLibertadores(){const c=state.continental;const stage=c.champion!==null?'Finalizada':c.round<6?'Fase de grupos • Rodada '+(c.round+1)+'/6':['Oitavas','Quartas','Semifinal','Final'][c.round-6];return `<section class="hero"><div><span class="eyebrow">COPA LIBERTADORES DA AMÉRICA</span><h2>🏆 Libertadores ${c.year}</h2><p>${stage}</p><button class="primary" id="simlib" ${c.champion!==null?'disabled':''}>▶ ${c.champion!==null?'COMPETIÇÃO ENCERRADA':'SIMULAR PRÓXIMA ETAPA'}</button></div><div class="ball">🏆</div></section><section class="panel"><h3>${c.champion!==null?'🏆 Campeão: '+getClubByUid(c.champion).name:'Fase de grupos'}</h3><p class="muted">32 clubes • 8 grupos de 4 • 6 rodadas e mata-mata em jogo único. Participantes simulados; não é o sorteio oficial da CONMEBOL.</p><div class="groupgrid">${c.groupTables.map((group,gi)=>`<div class="groupcard"><h4>GRUPO ${'ABCDEFGH'[gi]}</h4>${[...group].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)).map(t=>`<div class="groupteam"><span>${getClubByUid(t.uid).name}</span><b>${t.pts}</b></div>`).join('')}</div>`).join('')}</div></section><section class="panel"><h3>Últimos jogos</h3>${c.results.slice(-16).reverse().map(r=>`<div class="row"><span>${getClubByUid(r.a).name} × ${getClubByUid(r.b).name}</span><b>${r.x} - ${r.y}</b></div>`).join('')||'<p class="muted">A competição ainda não começou.</p>'}</section>`}

function renderSudamericana(){
 const c=state.sudamericana;
 const stage=c.champion!==null?'Finalizada':c.round<6?'Fase de grupos • Rodada '+(c.round+1)+'/6':['Oitavas','Quartas','Semifinal','Final'][c.round-6];
 return `<section class="hero"><div><span class="eyebrow">COPA SUL-AMERICANA</span><h2>🏆 Sul-Americana ${c.year}</h2><p>${stage}</p><button class="primary" id="simsud" ${c.champion!==null?'disabled':''}>▶ ${c.champion!==null?'COMPETIÇÃO ENCERRADA':'SIMULAR PRÓXIMA ETAPA'}</button></div><div class="ball">🌎</div></section><section class="panel"><h3>${c.champion!==null?'🏆 Campeão: '+getClubByUid(c.champion).name:'Fase de grupos'}</h3><p class="muted">Simulação simplificada: 32 clubes, oito grupos, mata-mata em jogo único. Não reproduz o regulamento oficial da CONMEBOL.</p><div class="groupgrid">${c.groupTables.map((group,gi)=>`<div class="groupcard"><h4>GRUPO ${'ABCDEFGH'[gi]}</h4>${[...group].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)).map(t=>`<div class="groupteam"><span>${getClubByUid(t.uid).name}</span><b>${t.pts}</b></div>`).join('')}</div>`).join('')}</div></section><section class="panel"><h3>Últimos jogos</h3>${c.results.slice(-16).reverse().map(r=>`<div class="row"><span>${getClubByUid(r.a).name} × ${getClubByUid(r.b).name}</span><b>${r.x} - ${r.y}</b></div>`).join('')||'<p class="muted">A competição ainda não começou.</p>'}</section>`;
}
const KEY='poifootb_carreira_v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch(e){};
function makeState(){return {year:2026,club:null,round:0,budget:35,players:teams.map((t,i)=>completeRoster(t[2].map((p,j)=>({id:i*100+j+1,name:p[0],pos:p[1],ovr:p[2],value:Math.max(1,Math.round((p[2]-65)*1.1*10)/10)})),t[0],0,i)),results:[],history:[],standings:teams.map((t,i)=>({id:i,pts:0,p:0,w:0,d:0,l:0,gf:0,ga:0})),page:'home',nextId:9999};}
if(!state||!Array.isArray(state.players)||state.players.length!==20)state=makeState();
ensureExpansion();if(!state.continental.groups)newLibertadores();if(!state.sudamericana||state.sudamericana.year!==state.year)newSudamericana();initExtraCups();
const $=id=>document.getElementById(id);const fmt=n=>'R$ '+Number(n).toFixed(1).replace('.',',')+' mi';
function save(){localStorage.setItem(KEY,JSON.stringify(state))}function alertMsg(s){$('toast').textContent=s;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2600)}
function tableSorted(){return [...state.standings].sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function fixtures(){let arr=teams.map((_,i)=>i),rounds=[];for(let r=0;r<19;r++){let pairs=[];for(let j=0;j<10;j++)pairs.push([arr[j],arr[19-j]]);rounds.push(pairs);arr=[arr[0],arr[19],...arr.slice(1,19)];}return rounds}
const schedule=fixtures();
function opponent(){return schedule[state.round]?.find(p=>p.includes(state.club))?.find(id=>id!==state.club)}
function strength(i){const arr=[...state.players[i]].sort((a,b)=>b.ovr-a.ovr).slice(0,11);return arr.reduce((s,p)=>s+p.ovr,0)/arr.length}
function goals(i,j){const power=strength(i)-strength(j);return Math.max(0,Math.min(6,Math.round(1.25+power/15+(Math.random()-.5)*3.6)))}
function updateTable(a,b,x,y){const A=state.standings[a],B=state.standings[b];A.p++;B.p++;A.gf+=x;A.ga+=y;B.gf+=y;B.ga+=x;if(x>y){A.w++;B.l++;A.pts+=3}else if(x<y){B.w++;A.l++;B.pts+=3}else{A.d++;B.d++;A.pts++;B.pts++}}
function play(){if(state.club===null)return;if(state.round>=19)return;const pairs=schedule[state.round];let summary;for(const [a,b] of pairs){let x=goals(a,b),y=goals(b,a);updateTable(a,b,x,y);recordGoals("league-0",clubUid(0,a),clubUid(0,b),x,y);if(a===state.club||b===state.club){const mine=a===state.club,own=mine?x:y,other=mine?y:x,opp=mine?b:a;summary={round:state.round+1,opponent:teams[opp][0],own,other,year:state.year};state.budget+=own>other?2:own===other?0.8:0.25;}}state.results.push(summary);state.round++;save();render();alertMsg('Rodada '+state.round+': '+summary.own+' x '+summary.other)}
function nextSeason(){if(state.round<19)return;const ranking=tableSorted(),pos=ranking.findIndex(t=>t.id===state.club)+1;state.history.push({year:state.year,position:pos,points:state.standings[state.club].pts});state.budget+=Math.max(5,40-pos*1.5);state.year++;state.scorers={year:state.year,competitions:{}};state.round=0;state.countryTables=countryLeagues.map((_,li)=>makeLeagueTable(li));state.countryRounds=countryLeagues.map(()=>0);state.results=[];state.standings=teams.map((t,i)=>({id:i,pts:0,p:0,w:0,d:0,l:0,gf:0,ga:0}));for(const team of state.players)for(const p of team){if(Math.random()<.4)p.ovr=Math.max(65,Math.min(93,p.ovr+(Math.random()<.65?1:-1)));p.value=Math.max(1,Math.round((p.ovr-65)*1.1*10)/10)}newLibertadores();newSudamericana();initExtraCups();save();render();alertMsg('Bem-vindo à temporada '+state.year+'!')}
function transfer(from,index,to){if(from===to)return;const p=state.players[from][index];if(!p)return;const cost=p.value;if(to===state.club&&state.budget<cost){alertMsg('Saldo insuficiente!');return}if(from===state.club){if(state.players[from].length<=4){alertMsg('Mantenha pelo menos quatro jogadores!');return}state.budget+=cost}else if(to===state.club)state.budget-=cost;state.players[from].splice(index,1);state.players[to].push(p);save();render();alertMsg(p.name+(to===state.club?' contratado!':' vendido!'))}
function chooseClub(id,li=0){state.scorers={year:state.year,competitions:{}};state.club=id;state.careerClub=id;state.careerCountry=li;state.page='home';state.budget=35;newLibertadores();newSudamericana();initExtraCups();save();render();alertMsg('Bem-vindo ao '+countryLeagues[li].clubs[id]+'!')}
function careerLeague(){return state.careerCountry||0}
function careerName(){return countryLeagues[careerLeague()].clubs[state.careerClub]}
function careerRoster(){return careerLeague()===0?state.players[state.careerClub]:state.foreignPlayers[careerLeague()][state.careerClub]}
function careerTable(){return careerLeague()===0?state.standings:state.countryTables[careerLeague()]}
function careerRank(){return careerLeague()===0?tableSorted():leagueRank(careerTable())}
function careerRound(){return careerLeague()===0?state.round:state.countryRounds[careerLeague()]}
function careerSchedule(){return careerLeague()===0?schedule:circleSchedule(countryLeagues[careerLeague()].clubs.length)}
function careerOpponent(){return careerSchedule()[careerRound()]?.find(p=>p.includes(state.careerClub))?.find(id=>id!==state.careerClub)}
function careerSeasonEnd(){return careerRound()>=careerSchedule().length}
function playCareer(){if(careerLeague()===0)return play();if(careerSeasonEnd())return;const li=careerLeague(),round=careerRound(),pairs=careerSchedule()[round];let summary;for(const [a,b] of pairs){let x=scorePower(getPower(clubUid(li,a)),getPower(clubUid(li,b))),y=scorePower(getPower(clubUid(li,b)),getPower(clubUid(li,a)));updateLeagueTable(state.countryTables[li],a,b,x,y);recordGoals("league-"+li,clubUid(li,a),clubUid(li,b),x,y);if(a===state.careerClub||b===state.careerClub){let mine=a===state.careerClub,own=mine?x:y,other=mine?y:x,opp=mine?b:a;summary={round:round+1,opponent:countryLeagues[li].clubs[opp],own,other,year:state.year};state.budget+=own>other?2:own===other?.8:.25;}}state.results.push(summary);state.countryRounds[li]++;save();render();alertMsg('Rodada '+(round+1)+': '+summary.own+' x '+summary.other)}
function nextCareerSeason(){if(!careerSeasonEnd())return;if(!cupsFinished()){alertMsg('Finalize a Libertadores, a Sul-Americana, a copa nacional do seu país e o Super Mundial (quando houver) antes de avançar!');return;}const pos=careerRank().findIndex(t=>t.id===state.careerClub)+1;state.history.push({year:state.year,position:pos,points:careerTable()[state.careerClub].pts,club:careerName(),league:countryLeagues[careerLeague()].name});state.budget+=Math.max(5,40-pos*1.5);state.year++;state.round=0;state.results=[];state.standings=teams.map((t,i)=>({id:i,pts:0,p:0,w:0,d:0,l:0,gf:0,ga:0}));state.countryTables=countryLeagues.map((_,li)=>makeLeagueTable(li));state.countryRounds=countryLeagues.map(()=>0);for(const roster of [...state.players,...state.foreignPlayers.filter(Boolean).flat()])for(const p of roster){if(Math.random()<.4)p.ovr=Math.max(60,Math.min(94,p.ovr+(Math.random()<.65?1:-1)));p.value=Math.max(1,Math.round((p.ovr-65)*1.1*10)/10)}newLibertadores();newSudamericana();initExtraCups();save();render();alertMsg('Bem-vindo à temporada '+state.year+'!')}
function allTransferClubs(){return countryLeagues.flatMap((l,li)=>l.clubs.map((name,ci)=>({li,ci,name,roster:li===0?state.players[ci]:state.foreignPlayers[li][ci]})))}
function transferInternational(fromLi,fromCi,index){const toLi=careerLeague(),toCi=state.careerClub;if(fromLi===toLi&&fromCi===toCi)return;const source=fromLi===0?state.players[fromCi]:state.foreignPlayers[fromLi][fromCi];const p=source[index];if(!p)return;if(p.placeholder){alertMsg('Este atleta ainda não tem identidade real confirmada.');return}if(source.length<=11){alertMsg('O clube vendedor precisa manter ao menos 11 jogadores.');return}if(state.budget<p.value){alertMsg('Saldo insuficiente!');return}state.budget-=p.value;source.splice(index,1);careerRoster().push(p);save();render();alertMsg(p.name+' contratado de '+countryLeagues[fromLi].clubs[fromCi]+'!')}
function sellInternational(index){const source=careerRoster(),p=source[index];if(!p)return;if(source.length<=11){alertMsg('Mantenha ao menos 11 jogadores no elenco!');return}const destinations=allTransferClubs().filter(t=>!(t.li===careerLeague()&&t.ci===state.careerClub));const buyer=destinations[Math.floor(Math.random()*destinations.length)];source.splice(index,1);buyer.roster.push(p);state.budget+=p.value;save();render();alertMsg(p.name+' vendido para '+buyer.name+'!')}

function renderHome(){const own=careerTable()[state.careerClub],pos=careerRank().findIndex(t=>t.id===state.careerClub)+1,opp=careerOpponent(),ended=careerSeasonEnd();return `<section class="hero"><div><span class="eyebrow">${ended?'FIM DA TEMPORADA':'PRÓXIMA PARTIDA'}</span><h2>${ended?'Temporada concluída':careerName()+' × '+countryLeagues[careerLeague()].clubs[opp]}</h2><p>${countryLeagues[careerLeague()].flag} ${countryLeagues[careerLeague()].name} • ${ended?'Confira a classificação':'Rodada '+(careerRound()+1)+' de '+careerSchedule().length}</p><button class="primary" id="play">${ended?(cupsFinished()?'AVANÇAR TEMPORADA →':'🏆 FINALIZE AS COMPETIÇÕES OBRIGATÓRIAS'):'▶ SIMULAR RODADA'}</button></div><div class="ball">⚽</div></section><section class="stats"><div class="stat"><small>POSIÇÃO</small><strong>${pos}º</strong></div><div class="stat"><small>PONTOS</small><strong>${own.pts}</strong></div><div class="stat"><small>VITÓRIAS</small><strong>${own.w}</strong></div><div class="stat"><small>ORÇAMENTO</small><strong>${fmt(state.budget)}</strong></div></section><div class="cols"><section class="panel"><h3>Últimos jogos</h3>${state.results.length?state.results.slice(-6).reverse().map(r=>`<div class="row"><span>vs ${r.opponent}</span><span class="result">${r.own} × ${r.other}</span></div>`).join(''):'<p class="muted">Nenhuma partida disputada ainda.</p>'}</section><section class="panel"><h3>Diretoria</h3><p class="muted">Conquiste títulos na sua liga e contrate atletas de toda a América do Sul.</p><p class="muted">As negociações ficam abertas durante toda a temporada.</p></section></div>`}
function renderSquad(){return `<section class="panel"><h3>Elenco de ${careerName()} (${careerRoster().length} jogadores)</h3><p class="notice">Elencos de demonstração: alguns nomes não estão verificados para novembro de 2026. As vagas “Atleta a confirmar” são provisórias.</p><div class="tablewrap"><table><thead><tr><th>JOGADOR</th><th>POSIÇÃO</th><th>OVERALL</th><th>VALOR</th><th>AÇÃO</th></tr></thead><tbody>${careerRoster().map((p,i)=>`<tr><td>${p.name}</td><td>${p.pos}</td><td class="rating">${p.ovr}</td><td>${fmt(p.value)}</td><td><button class="secondary" data-sell="${i}" ${careerRoster().length<=11?'disabled':''}>Vender</button></td></tr>`).join('')}</tbody></table></div></section>`}
function renderMarket(){let available=[];allTransferClubs().forEach(t=>{if(t.li!==careerLeague()||t.ci!==state.careerClub)t.roster.forEach((p,i)=>{if(!p.placeholder)available.push({...t,p,i})})});available.sort((a,b)=>b.p.ovr-a.p.ovr);return `<section class="panel"><h3>🌍 Mercado internacional</h3><p class="muted">Saldo: ${fmt(state.budget)} • Jogadores das 11 ligas. Clubes e vínculos são ilustrativos, não cadastros oficiais atualizados.</p><input id="filter" placeholder="Buscar jogador, clube ou país" aria-label="Buscar jogador, clube ou país" style="width:100%;margin:12px 0;padding:12px;border-radius:8px;border:1px solid #425844;background:#101a13;color:white"><div id="marketlist">${available.map(({p,li,ci,name,i})=>`<div class="marketrow" data-search="${(p.name+' '+name+' '+countryLeagues[li].name).toLowerCase()}"><div><b>${p.name}</b><small>${countryLeagues[li].flag} ${name} • ${p.pos} • GER ${p.ovr}</small></div><span class="price">${fmt(p.value)}</span><button class="secondary" data-buy="${li}:${ci}:${i}" ${state.budget<p.value?'disabled':''}>Contratar</button></div>`).join('')}</div></section>`}
function renderLeague(){return `<section class="panel"><h3>${countryLeagues[careerLeague()].flag} ${countryLeagues[careerLeague()].name} ${state.year}</h3><p class="muted">Formato simplificado de turno único, sem reproduzir o calendário oficial.</p><div class="tablewrap"><table><thead><tr><th>#</th><th>CLUBE</th><th>PTS</th><th>J</th><th>V</th><th>E</th><th>D</th><th>SG</th></tr></thead><tbody>${careerRank().map((t,i)=>`<tr class="${t.id===state.careerClub?'mine':''}"><td>${i+1}</td><td>${countryLeagues[careerLeague()].clubs[t.id]}</td><td><b>${t.pts}</b></td><td>${t.p}</td><td>${t.w}</td><td>${t.d}</td><td>${t.l}</td><td>${t.gf-t.ga}</td></tr>`).join('')}</tbody></table></div></section>`}
function renderHistory(){return `<section class="panel"><h3>Histórico do treinador</h3>${state.history.length?state.history.map(h=>`<div class="row"><b>Temporada ${h.year} • ${h.club||"Brasil"}</b><span>${h.position}º lugar • ${h.points} pontos</span></div>`).join(''):'<p class="muted">Termine a primeira temporada para registrar sua trajetória.</p>'}</section>`}

// Copas nacionais e Mundial de Clubes: formatos próprios simplificados, sem calendário oficial.
function makeKnockout(ids, label, year){return {year,label,round:0,remaining:[...ids],results:[],champion:null};}
function cupEntrants(li){const count=countryLeagues[li].clubs.length;const ids=Array.from({length:count},(_,i)=>clubUid(li,i));return ids.sort((a,b)=>getPower(b)-getPower(a)).slice(0,8);}
function initExtraCups(){
 if(!state.nationalCups||state.nationalCups.length!==countryLeagues.length||state.nationalCups.some(c=>c.year!==state.year))state.nationalCups=countryLeagues.map((l,li)=>makeKnockout(cupEntrants(li),'Copa Nacional - '+l.name,state.year));
 if(!state.worldCup||state.worldCup.year!==state.year){
  if((state.year-2029)%4===0){
   // 32 equipes sul-americanas como participantes demonstrativos; não são vagas oficiais FIFA.
   const entrants=[];for(let li=0;li<10;li++)for(const uid of cupEntrants(li).slice(0,li<2?5:3))entrants.push(uid);
   state.worldCup=makeKnockout(entrants.slice(0,32),'Super Mundial (simulação)',state.year);
  }else state.worldCup={year:state.year,notScheduled:true,champion:null};
 }
}
function simulateKnockout(cup){
 if(!cup||cup.notScheduled||cup.champion!==null)return;
 const winners=[];const stage={32:'16 avos',16:'Oitavas',8:'Quartas',4:'Semifinal',2:'Final'}[cup.remaining.length]||'Mata-mata';
 for(let i=0;i<cup.remaining.length;i+=2){const a=cup.remaining[i],b=cup.remaining[i+1];if(b===undefined){winners.push(a);continue}
 let x=scorePower(getPower(a),getPower(b)),y=scorePower(getPower(b),getPower(a));if(x===y){if(Math.random()<.5)x++;else y++}
 cup.results.push({stage,a,b,x,y});recordGoals(cup.label.startsWith('Super')?'world':'cup-'+Math.floor(a/1000),a,b,x,y);winners.push(x>y?a:b);
 }
 cup.remaining=winners;cup.round++;if(winners.length===1){cup.champion=winners[0];if(winners[0]===clubUid(careerLeague(),state.careerClub))state.budget+=cup.label.startsWith('Super')?65:12;}
 save();render();alertMsg(cup.champion!==null?'🏆 Campeão: '+getClubByUid(cup.champion).name:'Etapa '+stage+' concluída!');
}
function extraCupsFinished(){const copaDoPais=state.nationalCups?.[careerLeague()];return !!copaDoPais && copaDoPais.champion!==null && (!state.worldCup||state.worldCup.notScheduled||state.worldCup.champion!==null)}
function cupCard(cup,buttonId){if(cup.notScheduled)return `<section class="panel"><h3>🌍 Super Mundial</h3><p class="muted">Nesta simulação, acontece a cada quatro temporadas a partir de 2029. Próxima edição: ${state.year+(4-((state.year-2029)%4+4)%4)%4}.</p></section>`;
 return `<section class="panel"><h3>${cup.label} ${cup.year}</h3><p class="muted">${cup.champion!==null?'🏆 Campeão: '+getClubByUid(cup.champion).name:'Equipes restantes: '+cup.remaining.length+' • próxima fase eliminatória'}</p><button class="primary" id="${buttonId}" ${cup.champion!==null?'disabled':''}>▶ ${cup.champion!==null?'ENCERRADA':'SIMULAR PRÓXIMA FASE'}</button><div style="margin-top:18px">${cup.results.slice(-12).reverse().map(r=>`<div class="row"><span>${getClubByUid(r.a).name} × ${getClubByUid(r.b).name}</span><b>${r.x} - ${r.y}</b></div>`).join('')||'<p class="muted">Nenhum jogo disputado.</p>'}</div></section>`}
function renderNationalCups(){return `<section class="hero"><div><span class="eyebrow">COPAS NACIONAIS</span><h2>🏆 Copa nacional do seu país</h2><p>É obrigatório concluir apenas a copa do país do seu clube. As outras copas são opcionais.</p></div><div class="ball">🏆</div></section><div class="leaguechips">${countryLeagues.map((l,i)=>`<button class="chip ${state.cupCountry===i?'selected':''}" data-cupcountry="${i}">${l.flag} ${l.name}</button>`).join('')}</div>${cupCard(state.nationalCups[state.cupCountry||0],'simnational')}${statsWidget('cup-'+(state.cupCountry||0))}<p class="muted">Somente a copa nacional do país do seu clube é obrigatória para avançar a temporada. As copas dos demais países são opcionais. Os participantes são escolhidos por força estimada, não por sorteio oficial.</p>`}
function renderWorldCup(){return `<section class="hero"><div><span class="eyebrow">TORNEIO INTERNACIONAL</span><h2>🌍 Super Mundial de Clubes</h2><p>Edição fictícia com 32 participantes sul-americanos; mata-mata simplificado, sem clubes europeus.</p></div><div class="ball">🌍</div></section>${cupCard(state.worldCup,'simworld')}${statsWidget('world')}<p class="muted">Este Super Mundial é uma versão demonstrativa, não o Mundial de Clubes FIFA oficial. Na temporada em que ocorrer, será obrigatório concluí-lo para avançar.</p>`}

function render(){const club=state.club,li=careerLeague();$('year').textContent='📅 '+state.year;$('cash').textContent=club===null?'':'💰 '+fmt(state.budget);$('round').textContent=club===null?'NOVA CARREIRA':'RODADA '+Math.min(careerRound()+1,careerSchedule().length)+'/'+careerSchedule().length;$('clubtitle').textContent=club===null?'Seu próximo desafio':careerName();$('shield').textContent=club===null?'PF':li===0?teams[state.careerClub][1]:careerName().slice(0,3).toUpperCase();$('clubsubtitle').textContent=countryLeagues[li].flag+' '+countryLeagues[li].name;$('heading').textContent=({home:'Visão geral',squad:'Elenco',market:'Mercado internacional',league:'Campeonato',history:'Histórico',south:'Ligas Sul-Americanas',clubroster:'Elenco do clube',libertadores:'Libertadores',sudamericana:'Sul-Americana',national:'Copas Nacionais',world:'Super Mundial',statistics:'Artilharia e Assistências'})[state.page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));if(club===null){$('heading').textContent='Escolha seu clube';const sel=Number(state.selectCountry||0);$('app').innerHTML=`<div class="panel"><h3>🌎 Comece sua carreira no mundo</h3><p class="muted">Escolha qualquer clube das 11 ligas. Os elencos são uma base ilustrativa e incluem vagas a confirmar.</p><div class="leaguechips">${countryLeagues.map((l,i)=>`<button class="chip ${sel===i?'selected':''}" data-selectcountry="${i}">${l.flag} ${l.name}</button>`).join('')}</div><div class="choice">${countryLeagues[sel].clubs.map((name,i)=>`<button class="teamchoice" data-club="${i}"><span class="mini">${countryLeagues[sel].flag}</span>${name}</button>`).join('')}</div></div>`;document.querySelectorAll('[data-selectcountry]').forEach(b=>b.onclick=()=>{state.selectCountry=+b.dataset.selectcountry;render()});document.querySelectorAll('[data-club]').forEach(b=>b.onclick=()=>chooseClub(+b.dataset.club,sel));return}const pages={home:renderHome,squad:renderSquad,market:renderMarket,league:renderLeague,history:renderHistory,south:renderSouth,clubroster:renderClubRoster,libertadores:renderLibertadores,sudamericana:renderSudamericana,national:renderNationalCups,world:renderWorldCup,statistics:renderStatistics};$('app').innerHTML=pages[state.page]();if(state.page==='league')$('app').innerHTML+=statsWidget('league-'+careerLeague());if(state.page==='south')$('app').innerHTML+=statsWidget('league-'+state.country);if(state.page==='libertadores')$('app').innerHTML+=statsWidget('libertadores');if(state.page==='sudamericana')$('app').innerHTML+=statsWidget('sudamericana');if($('statsSelect'))$('statsSelect').onchange=e=>{state.statsComp=e.target.value;save();render()};document.querySelectorAll('[data-cupcountry]').forEach(b=>b.onclick=()=>{state.cupCountry=+b.dataset.cupcountry;save();render()});if($('simnational'))$('simnational').onclick=()=>simulateKnockout(state.nationalCups[state.cupCountry||0]);if($('simworld'))$('simworld').onclick=()=>simulateKnockout(state.worldCup);const sudBtn=$('simsud');if(sudBtn)sudBtn.onclick=simulateSudamericana;const playBtn=$('play');if(playBtn)playBtn.onclick=careerSeasonEnd()?nextCareerSeason:playCareer;document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{let [li,ci,i]=b.dataset.buy.split(':').map(Number);transferInternational(li,ci,i)});document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sellInternational(+b.dataset.sell));document.querySelectorAll('[data-country]').forEach(b=>b.onclick=()=>{state.country=+b.dataset.country;save();render()});document.querySelectorAll('[data-viewclub]').forEach(b=>b.onclick=()=>{state.viewClub=b.dataset.viewclub;state.page='clubroster';save();render()});if($('backclubs'))$('backclubs').onclick=()=>{state.page='south';save();render()};if($('simcountry'))$('simcountry').onclick=()=>{if(state.country===careerLeague()){alertMsg('Sua liga avança pela Central do Treinador.');return}simulateForeignRound(state.country);save();render()};if($('simlib'))$('simlib').onclick=simulateLibertadores;if($('filter'))$('filter').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('[data-search]').forEach(el=>el.style.display=el.dataset.search.includes(q)?'':'none')}}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;save();render()});$('reset').onclick=()=>{if(confirm('Apagar esta carreira e começar outra?')){state=makeState();ensureExpansion();newLibertadores();newSudamericana();initExtraCups();save();render()}};render();
